def word_squares(words):
    if not words:
        return []

    n = len(words[0])
    root = {'words': []}

    for word in words:
        node = root
        for ch in word:
            node = node.setdefault(ch, {'words': []})
            node['words'].append(word)

    def get_words_with_prefix(prefix):
        node = root
        for ch in prefix:
            if ch not in node:
                return []
            node = node[ch]
        return node['words']

    results = []
    squares = []

    def backtrack(row):
        if row == n:
            results.append(list(squares))
            return
        prefix = ''.join(squares[i][row] for i in range(row))
        for candidate in get_words_with_prefix(prefix):
            squares.append(candidate)
            backtrack(row + 1)
            squares.pop()

    for word in words:
        squares.append(word)
        backtrack(1)
        squares.pop()

    return results

